import { DomainError } from "./errors";

export const fulfilmentStates = ["placed", "paid", "packed", "shipped", "delivered"] as const;
export type FulfilmentState = (typeof fulfilmentStates)[number];
export type OrderState = FulfilmentState | "cancelled";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export class Order {
  private currentState: OrderState = "placed";

  public constructor(
    public readonly id: string,
    public readonly items: readonly OrderLine[],
  ) {
    if (!id.trim() || items.length === 0) {
      throw new DomainError("INVALID_ORDER", "An order must have an id and at least one item.");
    }
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public advanceTo(nextState: FulfilmentState): void {
    if (this.currentState === "cancelled") {
      throw new DomainError("INVALID_STATE_TRANSITION", "A cancelled order cannot be progressed.");
    }
    const expected = fulfilmentStates[fulfilmentStates.indexOf(this.currentState) + 1];
    if (nextState !== expected) {
      throw new DomainError(
        "INVALID_STATE_TRANSITION",
        `Orders can only move from ${this.currentState} to ${expected ?? "no further state"}.`,
      );
    }
    this.currentState = nextState;
  }

  public cancel(): void {
    if (this.currentState === "cancelled") {
      throw new DomainError("INVALID_CANCELLATION", "Order is already cancelled.");
    }
    if (this.currentState === "shipped" || this.currentState === "delivered") {
      throw new DomainError("INVALID_CANCELLATION", "A shipped order cannot be cancelled.");
    }
    this.currentState = "cancelled";
  }
}

